  ngOnInit(): void {
    this.initCols();
    this.getListItems();
  }

  //#endregion

  //#region methods
  initCols() {
    this.columns = [
      //
      {
        displayName: 'mangeDetails.refNo',
        colName: 'refNo',
        type: ColType.link,
        path: 'details',

      },

      //
      {
        displayName: 'general.createdBy',
        colName: 'createdBy',
        type: ColType.link,
      },
      //
      {
        displayName: 'general.createdAt',
        colName: 'createdAt',
        type: ColType.date,
      },
      //
      {
